62	
63	type UiMode = "none" | "static" | "vite-dev";
64	const FEEDBACK_EXPORT_FLUSH_INTERVAL_MS = 5_000;
65	const VITE_DEV_ASSET_PREFIXES = [
66	  "/@fs/",
67	  "/@id/",
68	  "/@react-refresh",
69	  "/@vite/",
70	  "/assets/",
71	  "/node_modules/",
72	  "/src/",
73	];
74	const VITE_DEV_STATIC_PATHS = new Set([
75	  "/apple-touch-icon.png",
76	  "/favicon-16x16.png",
77	  "/favicon-32x32.png",
78	  "/favicon.ico",
79	  "/favicon.svg",
80	  "/site.webmanifest",
81	  "/sw.js",
82	]);
