84	export function resolveViteHmrPort(serverPort: number): number {
85	  if (serverPort <= 55_535) {
86	    return serverPort + 10_000;
87	  }
88	  return Math.max(1_024, serverPort - 10_000);
89	}
90	
91	export function shouldServeViteDevHtml(req: ExpressRequest): boolean {
92	  const pathname = req.path;
93	  if (VITE_DEV_STATIC_PATHS.has(pathname)) return false;
94	  if (VITE_DEV_ASSET_PREFIXES.some((prefix) => pathname.startsWith(prefix))) return false;
95	  return req.accepts(["html"]) === "html";
96	}
