98	export function shouldEnablePrivateHostnameGuard(opts: {
99	  deploymentMode: DeploymentMode;
100	  deploymentExposure: DeploymentExposure;
101	}): boolean {
102	  return (
103	    opts.deploymentExposure === "private" &&
104	    (opts.deploymentMode === "local_trusted" || opts.deploymentMode === "authenticated")
105	  );
106	}
