108	export async function createApp(
109	  db: Db,
110	  opts: {
111	    uiMode: UiMode;
112	    serverPort: number;
113	    storageService: StorageService;
114	    feedbackExportService?: {
115	      flushPendingFeedbackTraces(input?: {
116	        companyId?: string;
117	        traceId?: string;
118	        limit?: number;
119	        now?: Date;
120	      }): Promise<unknown>;
121	    };
122	    databaseBackupService?: InstanceDatabaseBackupService;
123	    deploymentMode: DeploymentMode;
124	    deploymentExposure: DeploymentExposure;
125	    allowedHostnames: string[];
126	    bindHost: string;
127	    authReady: boolean;
128	    companyDeletionEnabled: boolean;
129	    instanceId?: string;
130	    hostVersion?: string;
131	    localPluginDir?: string;
132	    pluginMigrationDb?: Db;
133	    pluginWorkerManager?: PluginWorkerManager;
134	    betterAuthHandler?: express.RequestHandler;
135	    resolveSession?: (req: ExpressRequest) => Promise<BetterAuthSessionResult | null>;
136	  },
137	) {
138	  const app = express();
139	
140	  app.use(express.json({
141	    // Company import/export payloads can inline full portable packages.
142	    limit: "10mb",
143	    verify: (req, _res, buf) => {
144	      (req as unknown as { rawBody: Buffer }).rawBody = buf;
145	    },
146	  }));
147	  app.use(httpLogger);
148	  const privateHostnameGateEnabled = shouldEnablePrivateHostnameGuard({
149	    deploymentMode: opts.deploymentMode,
150	    deploymentExposure: opts.deploymentExposure,
151	  });
152	  const privateHostnameAllowSet = resolvePrivateHostnameAllowSet({
153	    allowedHostnames: opts.allowedHostnames,
154	    bindHost: opts.bindHost,
155	  });
156	  app.use(
157	    privateHostnameGuard({
158	      enabled: privateHostnameGateEnabled,
159	      allowedHostnames: opts.allowedHostnames,
160	      bindHost: opts.bindHost,
161	    }),
162	  );
163	  app.use(
164	    actorMiddleware(db, {
165	      deploymentMode: opts.deploymentMode,
166	      resolveSession: opts.resolveSession,
167	    }),
168	  );
169	  app.use("/api/auth", authRoutes(db));
170	  if (opts.betterAuthHandler) {
171	    app.all("/api/auth/{*authPath}", opts.betterAuthHandler);
172	  }
173	  app.use(llmRoutes(db));
174	
175	  const hostServicesDisposers = new Map<string, () => void>();
176	  const workerManager = opts.pluginWorkerManager ?? createPluginWorkerManager();
177	
178	  // Mount API routes
179	  const api = Router();
180	  api.use(boardMutationGuard());
181	  api.use(
182	    "/health",
183	    healthRoutes(db, {
184	      deploymentMode: opts.deploymentMode,
185	      deploymentExposure: opts.deploymentExposure,
186	      authReady: opts.authReady,
187	      companyDeletionEnabled: opts.companyDeletionEnabled,
188	    }),
189	  );
190	  api.use("/companies", companyRoutes(db, opts.storageService));
191	  api.use(companySkillRoutes(db));
192	  api.use(agentRoutes(db, { pluginWorkerManager: workerManager }));
193	  api.use(assetRoutes(db, opts.storageService));
194	  api.use(projectRoutes(db));
195	  api.use(issueRoutes(db, opts.storageService, {
196	    feedbackExportService: opts.feedbackExportService,
197	    pluginWorkerManager: workerManager,
198	  }));
199	  api.use(issueTreeControlRoutes(db));
200	  api.use(routineRoutes(db, { pluginWorkerManager: workerManager }));
201	  api.use(environmentRoutes(db, { pluginWorkerManager: workerManager }));
202	  api.use(executionWorkspaceRoutes(db));
203	  api.use(goalRoutes(db));
204	  api.use(approvalRoutes(db, { pluginWorkerManager: workerManager }));
205	  api.use(secretRoutes(db));
206	  api.use(costRoutes(db, { pluginWorkerManager: workerManager }));
207	  api.use(activityRoutes(db));
208	  api.use(dashboardRoutes(db));
209	  api.use(userProfileRoutes(db));
210	  api.use(sidebarBadgeRoutes(db));
211	  api.use(sidebarPreferenceRoutes(db));
212	  api.use(inboxDismissalRoutes(db));
213	  api.use(instanceSettingsRoutes(db));
214	  if (opts.databaseBackupService) {
215	    api.use(instanceDatabaseBackupRoutes(opts.databaseBackupService));
216	  }
217	  const pluginRegistry = pluginRegistryService(db);
218	  const eventBus = createPluginEventBus();
219	  setPluginEventBus(eventBus);
220	  const jobStore = pluginJobStore(db);
221	  const lifecycle = pluginLifecycleManager(db, { workerManager });
222	  const scheduler = createPluginJobScheduler({
223	    db,
224	    jobStore,
225	    workerManager,
226	  });
227	  const toolDispatcher = createPluginToolDispatcher({
228	    workerManager,
229	    lifecycleManager: lifecycle,
230	    db,
231	  });
232	  const jobCoordinator = createPluginJobCoordinator({
233	    db,
234	    lifecycle,
235	    scheduler,
236	    jobStore,
237	  });
238	  const hostServiceCleanup = createPluginHostServiceCleanup(lifecycle, hostServicesDisposers);
239	  let viteHtmlRenderer: ReturnType<typeof createCachedViteHtmlRenderer> | null = null;
240	  const loader = pluginLoader(
241	    db,
242	    {
243	      localPluginDir: opts.localPluginDir ?? DEFAULT_LOCAL_PLUGIN_DIR,
244	      migrationDb: opts.pluginMigrationDb,
245	    },
246	    {
247	      workerManager,
248	      eventBus,
249	      jobScheduler: scheduler,
250	      jobStore,
251	      toolDispatcher,
252	      lifecycleManager: lifecycle,
253	      instanceInfo: {
254	        instanceId: opts.instanceId ?? "default",
255	        hostVersion: opts.hostVersion ?? "0.0.0",
256	      },
257	      buildHostHandlers: (pluginId, manifest) => {
258	        const notifyWorker = (method: string, params: unknown) => {
259	          const handle = workerManager.getWorker(pluginId);
260	          if (handle) handle.notify(method, params);
261	        };
262	        const services = buildHostServices(db, pluginId, manifest.id, eventBus, notifyWorker, {
263	          pluginWorkerManager: workerManager,
264	        });
265	        hostServicesDisposers.set(pluginId, () => services.dispose());
266	        return createHostClientHandlers({
267	          pluginId,
268	          capabilities: manifest.capabilities,
269	          services,
270	        });
271	      },
272	    },
273	  );
274	  api.use(
275	    pluginRoutes(
276	      db,
277	      loader,
278	      { scheduler, jobStore },
279	      { workerManager },
280	      { toolDispatcher },
281	      { workerManager },
282	    ),
283	  );
284	  api.use(adapterRoutes());
285	  api.use(
286	    accessRoutes(db, {
287	      deploymentMode: opts.deploymentMode,
288	      deploymentExposure: opts.deploymentExposure,
289	      bindHost: opts.bindHost,
290	      allowedHostnames: opts.allowedHostnames,
291	    }),
292	  );
293	  app.use("/api", api);
294	  app.use("/api", (_req, res) => {
295	    res.status(404).json({ error: "API route not found" });
296	  });
297	  app.use(pluginUiStaticRoutes(db, {
298	    localPluginDir: opts.localPluginDir ?? DEFAULT_LOCAL_PLUGIN_DIR,
299	  }));
300	
301	  const __dirname = path.dirname(fileURLToPath(import.meta.url));
302	  if (opts.uiMode === "static") {
303	    // Try published location first (server/ui-dist/), then monorepo dev location (../../ui/dist)
304	    const candidates = [
305	      path.resolve(__dirname, "../ui-dist"),
306	      path.resolve(__dirname, "../../ui/dist"),
307	    ];
308	    const uiDist = candidates.find((p) => fs.existsSync(path.join(p, "index.html")));
309	    if (uiDist) {
310	      const indexHtml = applyUiBranding(fs.readFileSync(path.join(uiDist, "index.html"), "utf-8"));
311	      // Hashed asset files (Vite emits them under /assets/<name>.<hash>.<ext>)
312	      // never change once built, so they can be cached aggressively.
313	      app.use(
314	        "/assets",
315	        express.static(path.join(uiDist, "assets"), {
316	          maxAge: "1y",
317	          immutable: true,
318	        }),
319	      );
320	      // Non-hashed static files (favicon.ico, manifest, robots.txt, etc.):
321	      // short cache so operators who swap them out see the new version
322	      // reasonably fast. Override for `index.html` specifically — it is
323	      // served by this middleware for `/` and `/index.html`, and it must
324	      // never outlive the asset hashes it points at.
325	      app.use(
326	        express.static(uiDist, {
327	          maxAge: "1h",
328	          setHeaders(res, filePath) {
329	            if (path.basename(filePath) === "index.html") {
330	              res.set("Cache-Control", "no-cache");
331	            }
332	          },
333	        }),
334	      );
335	      // SPA fallback. Only for non-asset routes — if the browser asks for
336	      // /assets/something.js that doesn't exist, we must NOT serve the HTML
337	      // shell: the browser would try to load it as a JavaScript module, fail
338	      // with a MIME-type error, and cache that broken response. Return 404
339	      // instead. The index.html response itself is no-cache so a subsequent
340	      // deploy's updated asset hashes are picked up on next load.
341	      app.get(/.*/, (req, res) => {
342	        if (req.path.startsWith("/assets/")) {
343	          res.status(404).end();
344	          return;
345	        }
346	        res
347	          .status(200)
348	          .set("Content-Type", "text/html")
349	          .set("Cache-Control", "no-cache")
350	          .end(indexHtml);
351	      });
352	    } else {
353	      console.warn("[paperclip] UI dist not found; running in API-only mode");
354	    }
355	  }
356	
357	  if (opts.uiMode === "vite-dev") {
358	    const uiRoot = path.resolve(__dirname, "../../ui");
359	    const publicUiRoot = path.resolve(uiRoot, "public");
360	    const hmrPort = resolveViteHmrPort(opts.serverPort);
361	    const { createServer: createViteServer } = await import("vite");
362	    const vite = await createViteServer({
363	      root: uiRoot,
364	      appType: "custom",
365	      server: {
366	        middlewareMode: true,
367	        hmr: {
368	          host: opts.bindHost,
369	          port: hmrPort,
370	          clientPort: hmrPort,
371	        },
372	        allowedHosts: privateHostnameGateEnabled ? Array.from(privateHostnameAllowSet) : undefined,
373	      },
374	    });
375	    viteHtmlRenderer = createCachedViteHtmlRenderer({
376	      vite,
377	      uiRoot,
378	      brandHtml: applyUiBranding,
379	    });
380	    const renderViteHtml = viteHtmlRenderer;
381	
382	    if (fs.existsSync(publicUiRoot)) {
383	      app.use(express.static(publicUiRoot, { index: false }));
384	    }
385	    app.get(/.*/, async (req, res, next) => {
386	      if (!shouldServeViteDevHtml(req)) {
387	        next();
388	        return;
389	      }
390	      try {
391	        const html = await renderViteHtml.render(req.originalUrl);
392	        res.status(200).set({ "Content-Type": "text/html" }).end(html);
393	      } catch (err) {
394	        next(err);
395	      }
396	    });
397	    app.use(vite.middlewares);
398	  }
399	
400	  app.use(errorHandler);
401	
402	  jobCoordinator.start();
403	  scheduler.start();
404	  const feedbackExportTimer = opts.feedbackExportService
405	    ? setInterval(() => {
406	      void opts.feedbackExportService?.flushPendingFeedbackTraces().catch((err) => {
407	        logger.error({ err }, "Failed to flush pending feedback exports");
408	      });
409	    }, FEEDBACK_EXPORT_FLUSH_INTERVAL_MS)
410	    : null;
411	  feedbackExportTimer?.unref?.();
412	  if (opts.feedbackExportService) {
413	    void opts.feedbackExportService.flushPendingFeedbackTraces().catch((err) => {
414	      logger.error({ err }, "Failed to flush pending feedback exports");
415	    });
416	  }
417	  void toolDispatcher.initialize().catch((err) => {
418	    logger.error({ err }, "Failed to initialize plugin tool dispatcher");
419	  });
420	  const devWatcher = opts.uiMode === "vite-dev"
421	    ? createPluginDevWatcher(
422	      lifecycle,
423	      async (pluginId) => (await pluginRegistry.getById(pluginId))?.packagePath ?? null,
424	    )
425	    : null;
426	  void loader.loadAll().then((result) => {
427	    if (!result) return;
428	    for (const loaded of result.results) {
429	      if (devWatcher && loaded.success && loaded.plugin.packagePath) {
430	        devWatcher.watch(loaded.plugin.id, loaded.plugin.packagePath);
431	      }
432	    }
433	  }).catch((err) => {
434	    logger.error({ err }, "Failed to load ready plugins on startup");
435	  });
436	  process.once("exit", () => {
437	    if (feedbackExportTimer) clearInterval(feedbackExportTimer);
438	    devWatcher?.close();
439	    viteHtmlRenderer?.dispose();
440	    hostServiceCleanup.disposeAll();
441	    hostServiceCleanup.teardown();
442	  });
443	  process.once("beforeExit", () => {
444	    void flushPluginLogBuffer();
445	  });
446	
447	  return app;
448	}
